select tests.as_anon();
select tests.eq((select count(*) from public.claims)::int, 2, 'anonymous visitors see only published, undeleted claims');
select tests.eq((select count(*) from public.sources)::int, 2, 'anonymous visitors do not see draft sources');
select tests.eq((select count(*) from public.evidence)::int, 1, 'evidence on an unpublished source is hidden from visitors');
select tests.eq((select count(*) from public.source_assessments)::int, 1, 'draft assessments are hidden from visitors');
select tests.eq((select count(*) from public.entity_versions where entity_id = tests.id('c2'))::int, 0, 'draft claims have no public version history');
select tests.ok((select count(*) from public.entity_versions where entity_id = tests.id('c1')) = 1, 'published claims expose their version history');
select tests.eq((select count(*) from public.profiles)::int, 2, 'visitors only see profiles of published authors');
select tests.eq((select count(*) from public.collections)::int, 1, 'visitors only see public collections');
select tests.eq((select count(*) from public.collection_items)::int, 2, 'items pointing at unpublished claims are hidden from visitors');
select tests.eq((select public.get_shared_collection(tests.id('token-unlisted')) ->> 'title'), 'Alice unlisted', 'an unlisted collection opens through its link');
select tests.eq((select jsonb_array_length(public.get_shared_collection(tests.id('token-public')) -> 'items')), 2, 'a shared collection omits unpublished items');
select tests.ok((select public.get_shared_collection(tests.id('token-private'))) is null, 'a private collection never opens through its link');
select tests.ok((select public.get_shared_collection(tests.id('token-bob'))) is null, 'another private collection never opens through its link');
select tests.throws('select * from public.audit_logs', '42501', 'visitors cannot read the audit log');
select tests.throws('select * from public.notifications', '42501', 'visitors cannot read notifications');
select tests.throws('select * from public.bookmarks', '42501', 'visitors cannot read bookmarks');
select tests.throws($$insert into public.claims (title, category) values ('Anonymous claim', 'science')$$, '42501', 'visitors cannot create claims');
select tests.throws($$select public.decide_review(gen_random_uuid(), 'approved', null)$$, '42501', 'visitors cannot call workflow functions');
select tests.throws($$select * from public.admin_list_users()$$, '42501', 'visitors cannot list users');
select tests.reset();

select tests.as_user('alice');
select tests.eq((select count(*) from public.claims)::int, 2, 'a registered user sees only published claims');
select tests.eq((select count(*) from public.collections)::int, 4, 'a user sees own, public and shared collections only');
select tests.eq((select count(*) from public.bookmarks)::int, 1, 'a user sees only own bookmarks');
select tests.eq((select count(*) from public.notifications)::int, 2, 'a user sees only own notifications, including the one from a collection share');
select tests.eq((select count(*) from public.saved_views)::int, 1, 'a user sees own saved views');
select tests.eq((select count(*) from public.audit_logs)::int, 0, 'a user sees no audit log rows');
select tests.eq((select count(*) from public.review_items)::int, 0, 'a user sees no review items of others');
select tests.eq((select count(*) from public.content_revisions)::int, 0, 'a user sees no revisions of others');
select tests.eq((select count(*) from public.user_settings)::int, 1, 'a user sees only own settings');
select tests.eq(tests.affected($$update public.profiles set display_name = 'Hacked' where id = tests.id('bob')$$), 0, 'a user cannot rename someone else');
select tests.eq(tests.affected($$update public.profiles set display_name = 'Alice B' where id = tests.id('alice')$$), 1, 'a user can rename themselves');
select tests.throws($$update public.profiles set role = 'admin' where id = tests.id('alice')$$, '42501', 'a user cannot change their own role');
select tests.throws($$select public.set_user_role(tests.id('alice'), 'admin')$$, '42501', 'a user cannot call the role function');
select tests.throws($$insert into public.claims (title, category, author_id) values ('Plain user claim', 'science', tests.id('alice'))$$, '42501', 'a plain user cannot create claims');
select tests.throws($$insert into public.notifications (user_id, type) values (tests.id('alice'), 'new_evidence')$$, '42501', 'users cannot write notifications');
select tests.throws($$delete from public.claims where id = tests.id('c1')$$, '42501', 'users cannot delete claims');
select tests.throws($$insert into public.bookmarks (user_id, claim_id) values (tests.id('alice'), tests.id('c2'))$$, '42501', 'a user cannot bookmark an unpublished claim');
select tests.throws($$insert into public.collection_items (collection_id, claim_id, position) values (tests.id('k-bob'), tests.id('c1'), 1)$$, '42501', 'a user cannot add items to another collection');
select tests.throws($$insert into public.bookmarks (user_id, claim_id) values (tests.id('bob'), tests.id('c1'))$$, '42501', 'a user cannot bookmark on behalf of someone else');
select tests.eq(tests.affected($$update public.notifications set read_at = now()$$), 2, 'a user can mark only own notifications as read');
select tests.throws($$update public.notifications set type = 'review_decision'$$, '42501', 'a user can change nothing but the read flag');
select tests.eq(tests.affected($$update public.collections set title = 'Renamed' where id = tests.id('k-bob')$$), 0, 'a user cannot edit a collection they only have shared access to');
select tests.eq((select count(*) from public.collection_items where collection_id = tests.id('k-unlisted'))::int, 1, 'owners see items of their unlisted collection');
select tests.reset();

select tests.as_user('bob');
select tests.eq((select count(*) from public.collections)::int, 2, 'another user sees public collections and their own');
select tests.eq((select count(*) from public.collections where owner_id = tests.id('alice') and visibility <> 'public')::int, 0, 'private and unlisted collections do not leak');
select tests.reset();

select tests.as_user('rita');
select tests.eq((select count(*) from public.claims)::int, 3, 'a researcher sees published claims and their own drafts');
select tests.eq((select count(*) from public.claims where id = tests.id('c3'))::int, 0, 'a researcher cannot see another researcher''s draft');
select tests.eq((select count(*) from public.evidence)::int, 3, 'a researcher sees own unpublished evidence');
select tests.eq((select count(*) from public.review_items)::int, 0, 'a researcher sees only own review items');
select tests.reset();

select tests.as_user('ada');
select tests.eq((select count(*) from public.claims)::int, 5, 'an admin sees every claim including deleted ones');
select tests.ok((select count(*) from public.audit_logs) > 0, 'an admin can read the audit log');
select tests.eq((select count(*) from public.collections where id = tests.id('k-private'))::int, 0, 'admins cannot read private collections');
select tests.eq((select count(*) from public.bookmarks)::int, 0, 'admins cannot read bookmarks');
select tests.eq((select count(*) from public.notifications)::int, 0, 'admins cannot read other users'' notifications');
select tests.throws($$delete from public.claims where id = tests.id('c1')$$, '42501', 'even admins cannot hard-delete claims');
select tests.eq((select count(*) from public.admin_list_users())::int, 6, 'an admin can list users');
select tests.ok((select bool_and(email like '%@example.test') from public.admin_list_users()), 'the user list includes email addresses');
select tests.reset();

select tests.as_user('rita');
select tests.throws($$select * from public.admin_list_users()$$, '42501', 'a researcher cannot list users');
select tests.eq((select count(*) from public.audit_logs)::int, 0, 'a researcher sees no audit log rows');
select tests.reset();
